import{_ as e,o as i,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- RBD: Kernel RBD client supports copy-on-read","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- RBD: Kernel RBD client supports copy-on-read","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["RBD","Ceph","Kernel","Storage Optimization","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_Kernel_RBD_client_supports_copy-on-read.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_Kernel_RBD_client_supports_copy-on-read.md","lastUpdated":1780459816000}'),n={name:"posts/2015/CDS_Infernalis_Day_2.2_--_RBD_-_Kernel_RBD_client_supports_copy-on-read.md"};function r(s,l,a,p,_,c){return i(),t("div",null,[...l[0]||(l[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2015年3月6日</p><p><strong>参会人员</strong>： Lee, Yin Chen, [其他参会人员]</p><p><strong>会议主题</strong>： RBD（Rados Block Device）相关功能改进讨论</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>RBD差异导出功能</strong>：</p><ul><li>Lee提出了导出RBD克隆和父块差异的功能。</li><li>讨论了使用协作列表（collab list）提高性能的方案，并计划添加回调请求到类中。</li><li>目前该功能尚未实现，需要进一步开发。</li></ul></li><li><p><strong>性能改进</strong>：</p><ul><li>提出使用状态机技术优化RBD复制和写入操作。</li><li>讨论了在内核中使用与用户空间相同的状态机技术。</li><li>计划分两步进行：首先重构现有复制和写入代码，其次优化查找和跟踪操作。</li></ul></li><li><p><strong>对象映射</strong>：</p><ul><li>讨论了使用哈希表（hash table）和查找列表（lookup list）优化对象映射的性能。</li><li>认为使用哈希表可能比查找列表性能更好。</li><li>计划在实现复制和写入操作后，再进行优化。</li></ul></li><li><p><strong>异步操作</strong>：</p><ul><li>讨论了使用异步操作（AIO）提高性能。</li><li>认为AIO操作在内核中比用户空间更灵活。</li><li>计划进一步研究AIO操作在RBD中的应用。</li></ul></li><li><p><strong>用户空间工具</strong>：</p><ul><li>讨论了将通用选项传递给rdmap的方案。</li><li>认为无需修改用户空间工具，只需在RBD模块中添加复制和还原功能即可。</li></ul></li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Lee和Yin Chen负责实现RBD差异导出功能。</li><li>进一步研究使用状态机技术优化RBD复制和写入操作。</li><li>优化对象映射性能。</li><li>研究AIO操作在RBD中的应用。</li><li>将通用选项传递给rdmap。</li></ol><p><strong>备注</strong>：</p><ul><li>讨论中涉及到的计算机科学/ceph相关领域英文关键词：RBD, clone, parent, diff, collab list, callback, state machine, object map, AIO, kernel, user space, hash table, lookup list。</li></ul>',10)])])}const u=e(n,[["render",r]]);export{d as __pageData,u as default};
